    g.set("نمط_محسوب", (el, prop) => { needElD("نمط_محسوب", el); return getComputedStyle(el).getPropertyValue(String(prop)); });
    g.set("المستند", () => { requireDom("المستند"); return document; });
    const EVENTS = new Set(["beforeinput", "click", "dblclick", "input", "change", "keydown", "keyup", "pointerdown", "pointermove", "pointerup", "pointercancel", "focus", "blur", "scroll", "contextmenu", "paste", "cut", "drop", "dragover"]);
